from fastapi import FastAPI, Request, Depends, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()

class ContractConflictError(Exception):
    def __init__(self, contract_id: str):
        self.contract_id = contract_id

@app.exception_handler(ContractConflictError)
async def contract_conflict_handler(request: Request, exc: ContractConflictError):
    return JSONResponse(
        status_code=409,
        content={
            "error": "ContractStateConflict",
            "detail": f"Contract {exc.contract_id} is currently undergoing sealing and cannot accept amendments"
        }
    )

@app.post("/legal/contracts/{contract_id}/propose-amendment")
async def propose_amendment(
    contract_id: str,
    payload: AmendmentPayload,
    contract_svc: ContractService = Depends(get_contract_service),
    current_user: User = Depends(get_current_user)
):
    contract = await contract_svc.get_contract_by_id(contract_id)
    if not contract:
        raise HTTPException(status_code=404, detail="Contract not found")
    if current_user.organization_id not in contract.participant_org_ids and not current_user.is_legal_compliance:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to access or amend this contract")
    if contract.is_sealed:
        raise ContractConflictError(contract_id)
    return await contract_svc.add_amendment(contract_id, payload, current_user.id)
